import {escapeHtml as esc} from './agent-view.js';
const modules=['api','gui','runtime','ollama','llm','skills','nanobot','gepa','coordinator','worker','reflector','evaluator','reviewer'];
const time=value=>new Date(value).toLocaleString('zh-TW',{timeZone:'Asia/Taipei',hour12:false});
export function logsResultsView(state){
 const data=state.data;
 return `<section data-log-results><div class="card spaced"><p class="body-copy" role="status">${state.busy?'讀取中…':state.error?'更新失敗／保留上次紀錄':state.enabled?'自動更新最新紀錄':'更新已暫停'} · 最近成功 ${esc(state.lastSuccess?time(state.lastSuccess):'尚無')}<br>目前 ${data?.records.length||0} 筆 · 符合篩選 ${data?.matched||0} 筆 · 保留 ${data?.retained||0}／${data?.retentionLimit||10000} 筆 · 時間顯示 Asia/Taipei</p>${state.error?`<div class="error-banner" role="alert">${esc(state.error)}。請使用 WSL localhost GUI。</div>`:''}</div>
 <div class="card spaced log-records">${(data?.records||[]).map(r=>`<article class="log-record"><div class="log-record-heading"><span class="log-level log-${r.level.toLowerCase()}">${esc(r.level)}</span><strong>${esc(r.module)}</strong><time datetime="${esc(r.at)}">${esc(time(r.at))}</time><small>#${r.id}</small></div>${r.runId?`<button class="text-button" data-log-correlation="${esc(r.runId)}">${esc(r.runId)}</button>`:''}<pre class="log-message">${esc(r.message)}</pre>${Object.keys(r.details).length?`<details><summary>詳細資料</summary><pre class="log-details">${esc(JSON.stringify(r.details,null,2))}</pre></details>`:''}</article>`).join('')||'<div class="empty">尚無符合篩選的紀錄。新操作會記錄在這裡；升級前的角色 log 可在下方檢閱。</div>'}</div>
 <div class="actions card-actions"><button class="button secondary" data-log-older ${state.busy||!data?.nextBefore?'disabled':''}>載入較舊紀錄</button><span>查看較舊紀錄時暫停自動更新；最多檢閱 1,000 筆，套用篩選可縮小範圍。</span></div>
 <div class="card spaced"><h2>原始角色 Log</h2><p class="body-copy">${state.rawBusy?'讀取中…':'唯讀檢閱所選 run 的角色檔案；支援升級前的紀錄。'} · 不會重新執行實驗。</p>${state.rawError?`<div class="error-banner" role="alert">${esc(state.rawError)}</div>`:''}${state.raw?`<p class="body-copy">${esc(state.raw.runId)}／${esc(state.raw.role)} · ${state.raw.truncated?'僅顯示最後 200,000 bytes；完整檔案保留在本機':'完整內容'}</p><pre class="live-output log-raw">${esc(state.raw.content)}</pre>`:'<p class="muted">選擇下方 run 與角色，讀取原始 log。</p>'}</div></section>`;
}
export function logsView(state,runtime){
 const select=(name,values,label)=>`<label>${label}<select name="${name}" data-log-filter="${name}"><option value="">全部</option>${values.map(v=>`<option value="${v}" ${state.filters[name]===v?'selected':''}>${v}</option>`).join('')}</select></label>`;
 return `<div class="page-heading"><div><p class="eyebrow">LOCAL DEBUG JOURNAL</p><h1>模組 Log</h1><p>集中查看 API、GUI、Ollama、模型呼叫、技能與角色輸出。</p></div><div class="actions"><button class="button secondary" data-log-refresh>↻ 更新紀錄</button><button class="button secondary" data-log-toggle>${state.enabled?'暫停更新':'繼續更新'}</button><button class="button secondary" data-log-export>匯出目前 JSONL</button></div></div>
 <div class="demo-banner"><span class="info-icon">i</span><div><strong>本機持續紀錄 · 跨 GUI 重啟保留</strong><span>新紀錄保存在 WSL 專案；保留最近 10,000 筆。一般紀錄省略完整 prompt／reasoning，並遮蔽常見憑證欄位。Windows Ollama server.log 與 GPU-Z 仍需在 Windows 檢閱。</span></div></div>
 <form class="card spaced log-filters" id="debug-log-form">${select('module',state.data?.modules||modules,'模組')}${select('level',['DEBUG','INFO','WARNING','ERROR'],'等級')}<label>Run／暖機 ID<input name="runId" maxlength="80" value="${esc(state.filters.runId)}" placeholder="RUN-…／WARM-…／CHECK-…"></label><label>搜尋紀錄<input name="q" maxlength="200" value="${esc(state.filters.q)}" placeholder="timeout、model、錯誤訊息"></label><button type="submit" class="button primary">套用篩選</button><button type="button" class="button secondary" data-log-clear>清除篩選</button></form>
 ${logsResultsView(state)}
 <section class="card spaced"><div class="actions card-actions"><label>原始 Log 的 run<select data-log-raw-run><option value="">選擇近期 run</option>${(runtime.data?.runs||[]).map(r=>`<option value="${esc(r.id)}" ${state.rawRun===r.id?'selected':''}>${esc(r.id)} · ${esc(r.status)}</option>`).join('')}</select></label>${['coordinator','worker','reflector','evaluator','reviewer'].map(role=>`<button class="button secondary" data-log-role="${role}" ${!state.rawRun||state.rawBusy?'disabled':''}>${role}</button>`).join('')}</div></section>`;
}
